<h2>CRUD - Felhasználók</h2><?php if ($crudMsg): ?><p class="message ok"><?= htmlspecialchars($crudMsg) ?></p><?php endif; ?><h3><?= $editRow ? 'Felhasználó módosítása' : 'Új felhasználó' ?></h3><form method="post"><input type="hidden" name="id" value="<?= htmlspecialchars($editRow['id'] ?? 0) ?>"><div class="form-row"><label>Családi név</label><input name="csaladi_nev" value="<?= htmlspecialchars($editRow['csaladi_nev'] ?? '') ?>" required></div><div class="form-row"><label>Utónév</label><input name="uto_nev" value="<?= htmlspecialchars($editRow['uto_nev'] ?? '') ?>" required></div><div class="form-row"><label>Bejelentkezés</label><input name="bejelentkezes" value="<?= htmlspecialchars($editRow['bejelentkezes'] ?? '') ?>" required maxlength="12"></div><?php if (!$editRow): ?><div class="form-row"><label>Jelszó</label><input name="jelszo" type="password" placeholder="alapértelmezett: 12345"></div><?php endif; ?><button type="submit"><?= $editRow ? 'Mentés' : 'Hozzáadás' ?></button></form><table><thead><tr><th>ID</th><th>Családi név</th><th>Utónév</th><th>Bejelentkezés</th><th>Actions</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?= htmlspecialchars($r['id']) ?></td><td><?= htmlspecialchars($r['csaladi_nev']) ?></td><td><?= htmlspecialchars($r['uto_nev']) ?></td><td><?= htmlspecialchars($r['bejelentkezes']) ?></td><td class="actions"><a class="btn" href="crud&action=edit&id=<?= $r['id'] ?>">Edit</a><form method="post" style="display:inline" onsubmit="return confirm('Biztosan törli?')"><input type="hidden" name="crud_action" value="delete"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="danger" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table>